-- Veto initial schema.
--
-- Every table that holds workspace data carries workspace_id, and every query
-- in the store filters on it. Identifiers are prefixed ULIDs generated by the
-- application (see internal/id).

CREATE TABLE workspaces (
    id                     text PRIMARY KEY,
    name                   text NOT NULL,
    settings               jsonb NOT NULL DEFAULT '{}',
    active_policy_version  integer,
    created_at             timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
    id             text PRIMARY KEY,
    email          text NOT NULL,
    name           text NOT NULL,
    password_hash  text NOT NULL,
    created_at     timestamptz NOT NULL DEFAULT now(),
    last_login_at  timestamptz,
    disabled_at    timestamptz
);
CREATE UNIQUE INDEX users_email_key ON users (lower(email));

CREATE TABLE memberships (
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    user_id       text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role          text NOT NULL CHECK (role IN ('owner', 'admin', 'reviewer', 'viewer')),
    created_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, user_id)
);
CREATE INDEX memberships_user ON memberships (user_id);

CREATE TABLE invitations (
    id            text PRIMARY KEY,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    email         text NOT NULL,
    role          text NOT NULL CHECK (role IN ('owner', 'admin', 'reviewer', 'viewer')),
    token_hash    bytea NOT NULL UNIQUE,
    created_by    text REFERENCES users (id) ON DELETE SET NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NOT NULL,
    accepted_at   timestamptz,
    revoked_at    timestamptz
);
CREATE INDEX invitations_workspace ON invitations (workspace_id, created_at DESC);

CREATE TABLE sessions (
    token_hash    bytea PRIMARY KEY,
    user_id       text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_seen_at  timestamptz NOT NULL DEFAULT now(),
    expires_at    timestamptz NOT NULL,
    ip            text NOT NULL DEFAULT '',
    user_agent    text NOT NULL DEFAULT ''
);
CREATE INDEX sessions_user ON sessions (user_id);
CREATE INDEX sessions_expiry ON sessions (expires_at);

CREATE TABLE agents (
    id            text PRIMARY KEY,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    name          text NOT NULL,
    description   text NOT NULL DEFAULT '',
    vendor        text NOT NULL DEFAULT '',
    created_at    timestamptz NOT NULL DEFAULT now(),
    disabled_at   timestamptz,
    UNIQUE (workspace_id, name)
);

CREATE TABLE api_keys (
    id            text PRIMARY KEY,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    agent_id      text REFERENCES agents (id) ON DELETE CASCADE,
    name          text NOT NULL,
    kind          text NOT NULL CHECK (kind IN ('agent', 'admin')),
    prefix        text NOT NULL,
    secret_hash   bytea NOT NULL UNIQUE,
    created_by    text REFERENCES users (id) ON DELETE SET NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_used_at  timestamptz,
    revoked_at    timestamptz,
    CHECK ((kind = 'agent') = (agent_id IS NOT NULL))
);
CREATE INDEX api_keys_workspace ON api_keys (workspace_id, created_at DESC);

CREATE TABLE tools (
    workspace_id      text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    name              text NOT NULL,
    description       text NOT NULL DEFAULT '',
    risk_class        text NOT NULL CHECK (risk_class IN ('read', 'low', 'medium', 'high', 'critical')),
    reversible        boolean NOT NULL DEFAULT false,
    pack              text NOT NULL DEFAULT 'general',
    safer             jsonb NOT NULL DEFAULT '[]',
    auto_confidence   real CHECK (auto_confidence BETWEEN 0 AND 1),
    risk_ceiling      real CHECK (risk_ceiling BETWEEN 0 AND 1),
    block_confidence  real CHECK (block_confidence BETWEEN 0 AND 1),
    double_check      boolean,
    fail_mode         text NOT NULL DEFAULT 'closed' CHECK (fail_mode IN ('closed', 'open')),
    max_per_hour      integer CHECK (max_per_hour > 0),
    step_up           boolean NOT NULL DEFAULT false,
    registered        boolean NOT NULL DEFAULT true,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, name)
);

CREATE TABLE policy_versions (
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    version       integer NOT NULL,
    source        text NOT NULL,
    note          text NOT NULL DEFAULT '',
    created_by    text REFERENCES users (id) ON DELETE SET NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    activated_at  timestamptz,
    PRIMARY KEY (workspace_id, version)
);

-- Workspace overrides of question packs. Built-in packs ship in the binary;
-- a row here with active = true replaces the built-in pack of the same name.
CREATE TABLE question_packs (
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    name          text NOT NULL,
    version       integer NOT NULL,
    definition    jsonb NOT NULL,
    created_by    text REFERENCES users (id) ON DELETE SET NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    active        boolean NOT NULL DEFAULT false,
    PRIMARY KEY (workspace_id, name, version)
);
CREATE UNIQUE INDEX question_packs_one_active ON question_packs (workspace_id, name) WHERE active;

CREATE TABLE actions (
    id                 text PRIMARY KEY,
    workspace_id       text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    agent_id           text NOT NULL REFERENCES agents (id),
    tool               text NOT NULL,
    args               jsonb NOT NULL,
    args_hash          bytea NOT NULL,
    principal_id       text NOT NULL DEFAULT '',
    principal_display  text NOT NULL DEFAULT '',
    request            text NOT NULL DEFAULT '',
    untrusted          jsonb NOT NULL DEFAULT '[]',
    context            jsonb NOT NULL DEFAULT '{}',
    source             text NOT NULL DEFAULT 'api' CHECK (source IN ('api', 'mcp', 'connection')),
    idempotency_key    text,
    status             text NOT NULL CHECK (status IN ('evaluating', 'pending_review', 'approved', 'denied', 'expired')),
    options            jsonb NOT NULL DEFAULT '[]',
    ranking            jsonb NOT NULL DEFAULT '[]',
    hold_reasons       jsonb NOT NULL DEFAULT '[]',
    policy_version     integer,
    received_at        timestamptz NOT NULL DEFAULT now(),
    decided_at         timestamptz,
    review_deadline    timestamptz,
    reminded_at        timestamptz,
    redacted_at        timestamptz
);
CREATE UNIQUE INDEX actions_idempotency ON actions (workspace_id, agent_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX actions_workspace_received ON actions (workspace_id, received_at DESC);
CREATE INDEX actions_pending ON actions (workspace_id, review_deadline) WHERE status = 'pending_review';
CREATE INDEX actions_pending_deadline ON actions (review_deadline) WHERE status = 'pending_review';
CREATE INDEX actions_tool ON actions (workspace_id, tool, received_at DESC);
CREATE INDEX actions_agent ON actions (workspace_id, agent_id, received_at DESC);
CREATE INDEX actions_retention ON actions (received_at) WHERE redacted_at IS NULL;

CREATE TABLE evaluations (
    id            text PRIMARY KEY,
    action_id     text NOT NULL REFERENCES actions (id) ON DELETE CASCADE,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    stage         text NOT NULL CHECK (stage IN ('gate', 'rate_limit', 'model', 'model_recheck')),
    provider      text NOT NULL DEFAULT '',
    model         text NOT NULL DEFAULT '',
    request       jsonb,
    response      jsonb,
    result        jsonb NOT NULL DEFAULT '{}',
    latency_ms    integer NOT NULL DEFAULT 0,
    input_tokens  integer NOT NULL DEFAULT 0,
    error         text NOT NULL DEFAULT '',
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX evaluations_action ON evaluations (action_id, created_at);
CREATE INDEX evaluations_workspace_stage ON evaluations (workspace_id, stage, created_at DESC);

CREATE TABLE decisions (
    action_id         text PRIMARY KEY REFERENCES actions (id) ON DELETE CASCADE,
    workspace_id      text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    option            text NOT NULL CHECK (option IN ('proceed', 'proceed_safer', 'stop')),
    outcome           text NOT NULL CHECK (outcome IN ('approved', 'denied', 'expired')),
    decided_by        text NOT NULL CHECK (decided_by IN ('model', 'human', 'policy', 'failsafe', 'expiry')),
    reviewer_id       text REFERENCES users (id) ON DELETE SET NULL,
    final_tool        text NOT NULL DEFAULT '',
    final_args        jsonb,
    confidence        real,
    risk              real,
    model_choice      text,
    model_confidence  real,
    reasons           jsonb NOT NULL DEFAULT '[]',
    thresholds        jsonb NOT NULL DEFAULT '{}',
    note              text NOT NULL DEFAULT '',
    review_seconds    real,
    created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX decisions_workspace_time ON decisions (workspace_id, created_at DESC);

CREATE TABLE grants (
    id            text PRIMARY KEY,
    action_id     text NOT NULL REFERENCES actions (id) ON DELETE CASCADE,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    tool          text NOT NULL,
    args_hash     bytea NOT NULL,
    key_id        text NOT NULL,
    expires_at    timestamptz NOT NULL,
    consumed_at   timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX grants_action ON grants (action_id);

CREATE TABLE outcomes (
    id            text PRIMARY KEY,
    action_id     text NOT NULL REFERENCES actions (id) ON DELETE CASCADE,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    status        text NOT NULL CHECK (status IN ('succeeded', 'failed', 'reversed', 'complaint')),
    detail        jsonb NOT NULL DEFAULT '{}',
    reported_by   text NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX outcomes_action ON outcomes (action_id, created_at);
CREATE INDEX outcomes_workspace ON outcomes (workspace_id, created_at DESC);

CREATE TABLE audits (
    id            text PRIMARY KEY,
    action_id     text NOT NULL UNIQUE REFERENCES actions (id) ON DELETE CASCADE,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    reason        text NOT NULL CHECK (reason IN ('sample', 'outcome')),
    verdict       text CHECK (verdict IN ('correct', 'should_be_safer', 'should_hold', 'should_block')),
    reviewer_id   text REFERENCES users (id) ON DELETE SET NULL,
    note          text NOT NULL DEFAULT '',
    created_at    timestamptz NOT NULL DEFAULT now(),
    reviewed_at   timestamptz
);
CREATE INDEX audits_open ON audits (workspace_id, created_at) WHERE verdict IS NULL;
CREATE INDEX audits_reviewed ON audits (workspace_id, reviewed_at DESC) WHERE verdict IS NOT NULL;

CREATE TABLE signing_keys (
    id               text PRIMARY KEY,
    workspace_id     text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    key_id           text NOT NULL,
    public_key       bytea NOT NULL,
    private_key_enc  bytea NOT NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    retired_at       timestamptz,
    UNIQUE (workspace_id, key_id)
);
CREATE UNIQUE INDEX signing_keys_one_active ON signing_keys (workspace_id) WHERE retired_at IS NULL;

CREATE TABLE ledger_heads (
    workspace_id  text PRIMARY KEY REFERENCES workspaces (id) ON DELETE CASCADE,
    seq           bigint NOT NULL,
    hash          bytea NOT NULL
);

CREATE TABLE ledger_entries (
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    seq           bigint NOT NULL,
    kind          text NOT NULL,
    action_id     text,
    actor         text NOT NULL,
    payload       jsonb NOT NULL,
    prev_hash     bytea NOT NULL,
    hash          bytea NOT NULL,
    created_at    timestamptz NOT NULL,
    PRIMARY KEY (workspace_id, seq)
);
CREATE INDEX ledger_entries_action ON ledger_entries (action_id) WHERE action_id IS NOT NULL;
CREATE INDEX ledger_entries_kind ON ledger_entries (workspace_id, kind, seq DESC);

CREATE TABLE ledger_checkpoints (
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    seq           bigint NOT NULL,
    hash          bytea NOT NULL,
    key_id        text NOT NULL,
    signature     bytea NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, seq)
);

CREATE TABLE connections (
    id             text PRIMARY KEY,
    workspace_id   text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    name           text NOT NULL,
    description    text NOT NULL DEFAULT '',
    base_url       text NOT NULL,
    auth_scheme    text NOT NULL CHECK (auth_scheme IN ('none', 'bearer', 'header', 'basic')),
    header_name    text NOT NULL DEFAULT '',
    secret_enc     bytea,
    allow_methods  text[] NOT NULL DEFAULT '{GET,POST,PUT,PATCH,DELETE}',
    allow_private  boolean NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    rotated_at     timestamptz,
    disabled_at    timestamptz,
    UNIQUE (workspace_id, name)
);

CREATE TABLE mcp_servers (
    id             text PRIMARY KEY,
    workspace_id   text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    name           text NOT NULL,
    upstream_url   text NOT NULL,
    connection_id  text REFERENCES connections (id) ON DELETE SET NULL,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    disabled_at    timestamptz,
    UNIQUE (workspace_id, name)
);

CREATE TABLE webhooks (
    id            text PRIMARY KEY,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    url           text NOT NULL,
    description   text NOT NULL DEFAULT '',
    events        text[] NOT NULL,
    secret_enc    bytea NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    disabled_at   timestamptz
);

CREATE TABLE webhook_deliveries (
    id               text PRIMARY KEY,
    webhook_id       text NOT NULL REFERENCES webhooks (id) ON DELETE CASCADE,
    workspace_id     text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    event            text NOT NULL,
    payload          jsonb NOT NULL,
    status           text NOT NULL CHECK (status IN ('pending', 'delivered', 'failed')),
    attempts         integer NOT NULL DEFAULT 0,
    response_status  integer,
    last_error       text NOT NULL DEFAULT '',
    next_attempt_at  timestamptz NOT NULL DEFAULT now(),
    created_at       timestamptz NOT NULL DEFAULT now(),
    delivered_at     timestamptz
);
CREATE INDEX webhook_deliveries_due ON webhook_deliveries (next_attempt_at) WHERE status = 'pending';
CREATE INDEX webhook_deliveries_webhook ON webhook_deliveries (webhook_id, created_at DESC);

CREATE TABLE integrations (
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    kind          text NOT NULL CHECK (kind IN ('slack')),
    config        jsonb NOT NULL DEFAULT '{}',
    secret_enc    bytea,
    updated_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, kind)
);

-- Slack messages posted for held actions, so they can be updated once the
-- action is decided.
CREATE TABLE slack_messages (
    action_id     text PRIMARY KEY REFERENCES actions (id) ON DELETE CASCADE,
    workspace_id  text NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
    channel       text NOT NULL,
    ts            text NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now()
);
